<script lang="ts" module>
    /** Tracks if any tooltip is currently showing (for immediate show on warm hover) */
    let tooltipWarm = $state(false);
    let warmTimeout: ReturnType<typeof setTimeout> | null = null;
    const WARM_DURATION = 400; // ms to stay "warm" after leaving a tooltip

    function setWarm() {
        tooltipWarm = true;
        if (warmTimeout) clearTimeout(warmTimeout);
        warmTimeout = null;
    }

    function startCooldown() {
        if (warmTimeout) clearTimeout(warmTimeout);
        warmTimeout = setTimeout(() => {
            tooltipWarm = false;
            warmTimeout = null;
        }, WARM_DURATION);
    }
</script>

<script lang="ts">
    import Theme from "./Theme.svelte";
    import type { Snippet } from "svelte";

    /**
     * A tooltip using CSS Anchor Positioning for automatic overflow handling.
     * Displays on hover (with delay) or focus (immediate).
     * Supports "warming" - if a tooltip was recently shown, new tooltips appear instantly.
     * @supports prefers-reduced-motion
     * @cssprop --delay - Hover delay before showing. (Default: 0.4s)
     * @cssprop --tooltip-offset - Gap between the anchor and the tooltip. (Default: var(--space-xs))
     * @cssprop --tooltip-padding-block - Block padding of the tooltip. (Default: var(--space-xxs))
     * @cssprop --tooltip-padding-inline - Inline padding of the tooltip. (Default: var(--space-xs))
     * @cssprop --tooltip-font-size - Font size of the tooltip. (Default: max(0.75rem, 11px))
     * @cssprop --tooltip-max-width - Maximum width of the tooltip. (Default: 25ch)
     */
    let {
        children,
        tip,
        open,
    }: {
        /** Content to trigger the tooltip */
        children: Snippet;
        /** The content of the tooltip */
        tip: string | Snippet;
        /** Force tooltip open (for demos) */
        open?: boolean;
    } = $props();

    const id = crypto.randomUUID();
    const anchorName = `--tooltip-${id}`;

    let hovering = $state(false);

    function handleMouseEnter() {
        hovering = true;
        setWarm();
    }

    function handleMouseLeave() {
        hovering = false;
        startCooldown();
    }
</script>

<span 
    class="Tooltip" 
    class:open 
    class:warm={tooltipWarm}
    class:hovering
    role="group"
    style="anchor-name: {anchorName};"
    onmouseenter={handleMouseEnter}
    onmouseleave={handleMouseLeave}
>
    <span 
        class="TooltipContent" 
        id={id} 
        role="tooltip"
        style="position-anchor: {anchorName};"
    >
        <Theme theme="invert">
            {#if typeof tip === "string"}
                {@html tip}
            {:else}
                {@render tip()}
            {/if}
        </Theme>
    </span>
    <span class="TooltipTrigger" aria-describedby={id}>
        {@render children()}
    </span>
</span>

<style>
    .Tooltip {
        position: relative;
        display: inline-flex;
        vertical-align: var(--vertical-align, text-bottom);
    }

    .TooltipContent {
        position: fixed;
        position-area: block-start center;
        position-try-fallbacks: flip-block;
        margin-block-end: var(--tooltip-offset, var(--space-xs));
        background: var(--tooltip-background, var(--surface-background));
        border: var(--tooltip-border, var(--surface-border));
        border-radius: var(--tooltip-border-radius, var(--surface-border-radius));
        box-shadow: var(--tooltip-shadow, var(--surface-shadow));
        padding-block: var(--tooltip-padding-block, var(--space-xxs));
        padding-inline: var(--tooltip-padding-inline, var(--space-xs));
        font-size: var(--tooltip-font-size, max(0.75rem, 11px));
        line-height: var(--font-line-height-tight);
        font-weight: var(--font-weight-normal);
        color: var(--tooltip-color, var(--text-color-p));
        max-width: var(--tooltip-max-width, 25ch);
        width: max-content;
        text-align: center;
        opacity: 0;
        pointer-events: none;
    }

    .TooltipContent :global(code) {
        font-weight: var(--font-weight-medium);
    }

    .TooltipContent :global(strong),
    .TooltipContent :global(b) {
        font-weight: var(--font-weight-semibold);
    }

    .TooltipTrigger {
        display: inline-flex;
        align-items: center;
    }

    .Tooltip.hovering:not(.open) .TooltipContent {
        opacity: 1;
        transition: opacity 0s var(--delay, 0.4s);
    }

    .Tooltip.hovering.warm:not(.open) .TooltipContent {
        transition-delay: 0s;
    }


    .Tooltip:has(.TooltipTrigger :focus-visible) .TooltipContent,
    .Tooltip:focus-within .TooltipContent {
        opacity: 1;
        transition-delay: 0s;
    }

    .Tooltip.open .TooltipContent {
        opacity: 1;
    }

    @media (prefers-reduced-motion: reduce) {
        .TooltipContent {
            transition: none;
        }
    }
</style>
